/**
 * WorkspaceLayout — persistent shell for all /p/:projectId/... routes.
 *
 * Provides:
 *   - Topbar with logo, project name, and snapshot revision badge
 *   - Nav rail with Overview, Map, Dependencies, Opportunities, Ask, Proposals
 *   - File tree panel (synced with WorkspaceContext.selectedEntity)
 *   - Outlet for page content
 *
 * The WorkspaceProvider wraps this layout so all child pages share context.
 */

import { useEffect } from 'react'
import { Link, NavLink, Outlet, useParams } from 'react-router-dom'
import { useNavigate } from 'react-router-dom'
import { RepositoryTree } from '../../components/tree/RepositoryTree'
import { WorkspaceProvider, useWorkspace } from '../../contexts/WorkspaceContext'
import type { FileRecord } from '../../types/v1'
import { getAllFiles } from '../../services/v1/api'

// ── Nav items ──────────────────────────────────────────────────────────────

interface NavItem {
  to: string
  label: string
  icon: string
  ariaLabel: string
}

function navItems(projectId: string, snapshotId: string): NavItem[] {
  const base = `/p/${projectId}/s/${snapshotId}`
  return [
    { to: `${base}/overview`, label: 'Overview', icon: '◎', ariaLabel: 'Repository overview' },
    { to: `${base}/map`, label: 'Map', icon: '⊞', ariaLabel: 'Structure map' },
    { to: `${base}/dependencies`, label: 'Dependencies', icon: '⟶', ariaLabel: 'Dependencies and change impact' },
    { to: `${base}/opportunities/reuse`, label: 'Opportunities', icon: '◈', ariaLabel: 'Code opportunities' },
    { to: `${base}/ask`, label: 'Ask Grepo', icon: '⬡', ariaLabel: 'Ask Grepo' },
    { to: `${base}/proposals`, label: 'Proposals', icon: '✦', ariaLabel: 'Proposals' },
  ]
}

// ── Inner layout (uses workspace context) ──────────────────────────────────

function WorkspaceInner() {
  const { projectId = '', snapshotId = '' } = useParams<{ projectId: string; snapshotId: string }>()
  const ws = useWorkspace()

  // Load workspace on mount or route change
  useEffect(() => {
    if (!projectId) return
    ws.loadWorkspace(projectId, snapshotId || null)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projectId, snapshotId])

  // Load file list when snapshot changes
  useEffect(() => {
    const snap = ws.snapshot
    if (!snap || !projectId) return

    getAllFiles(projectId, snap.id)
      .then(files => ws.setFiles(files))
      .catch(() => { /* non-fatal */ })
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ws.snapshot?.id])

  const activeSnapshotId = ws.snapshot?.id ?? snapshotId
  const items = projectId ? navItems(projectId, activeSnapshotId) : []

  const revisionLabel = ws.snapshot?.source.resolved_commit
    ? ws.snapshot.source.resolved_commit.slice(0, 12)
    : ws.snapshot?.source.archive_digest?.slice(0, 12) ?? null

  function handleSelectFile(file: FileRecord) {
    ws.selectEntity({
      entityId: `file:${file.path}`,
      kind: 'file',
      path: file.path,
      fileId: file.id,
    })
  }

  return (
    <div className="grepo-app">
      {/* ── Topbar ── */}
      <header className="topbar" role="banner">
        <Link to="/" className="topbar__brand" aria-label="Grepo home">
          <img src="/grepo-logo.png" alt="" className="topbar__logo" aria-hidden="true" />
          <span className="topbar__wordmark">Grepo</span>
        </Link>

        <div className="topbar__project" aria-label="Current project">
          {ws.projectName ? (
            <>
              <span className="topbar__project-name" title={ws.projectName}>
                {ws.projectName}
              </span>
              {revisionLabel && (
                <span
                  className="topbar__badge topbar__badge--revision"
                  title={`Resolved commit: ${ws.snapshot?.source.resolved_commit ?? 'local archive'}`}
                >
                  {revisionLabel}
                </span>
              )}
            </>
          ) : (
            <span className="topbar__project-name" style={{ color: 'var(--grepo-text-secondary)' }}>
              {ws.loading ? 'Loading…' : 'No project'}
            </span>
          )}
        </div>

        <div className="topbar__actions">
          <Link to="/" className="btn btn--ghost btn--sm">
            ＋ New import
          </Link>
        </div>
      </header>

      {/* ── Main workspace ── */}
      <div className="workspace-layout" style={{ flex: 1 }}>
        {/* Nav rail */}
        <nav className="nav-rail" aria-label="Workspace navigation">
          <span className="nav-group-label">Navigate</span>
          {items.map(item => (
            <NavLink
              key={item.to}
              to={item.to}
              className={({ isActive }) =>
                `nav-item${isActive ? ' nav-item--active' : ''}`
              }
              aria-label={item.ariaLabel}
            >
              <span className="nav-item__icon" aria-hidden="true" style={{ fontSize: 14 }}>
                {item.icon}
              </span>
              {item.label}
            </NavLink>
          ))}

          <div className="nav-divider" />
          <span className="nav-group-label">Source</span>
          <NavLink
            to="/"
            className="nav-item"
            aria-label="Import a new repository"
          >
            <span className="nav-item__icon" aria-hidden="true" style={{ fontSize: 14 }}>↑</span>
            Import
          </NavLink>
        </nav>

        {/* File tree */}
        <nav className="tree-panel" aria-label="Repository file tree">
          {ws.loading ? (
            <div className="tree-message" role="status">
              <span className="spinner" style={{ display: 'inline-block', marginRight: 8 }} aria-hidden="true" />
              Loading files…
            </div>
          ) : ws.files.length > 0 ? (
            <RepositoryTree
              files={ws.files}
              selectedPath={ws.selectedEntity?.path ?? null}
              onSelect={handleSelectFile}
            />
          ) : (
            <>
              <div className="tree-panel__header">
                <h2 className="tree-panel__title">Files</h2>
                <span className="tree-panel__count">—</span>
              </div>
              <p className="tree-message">
                {ws.error ? ws.error : 'No files loaded.'}
              </p>
            </>
          )}
        </nav>

        {/* Page content */}
        <main className="content-area" id="main-content" aria-label="Page content">
          {ws.error && !ws.loading && (
            <div className="alert alert--error" style={{ margin: 24 }} role="alert">
              {ws.error}
              <button
                type="button"
                style={{ marginLeft: 12, border: 0, background: 'none', cursor: 'pointer', fontWeight: 600 }}
                onClick={ws.clearError}
              >
                Dismiss
              </button>
            </div>
          )}
          <Outlet />
        </main>
      </div>
    </div>
  )
}

// ── Project root (redirects to latest snapshot) ───────────────────────────

function ProjectRoot() {
  const { projectId = '' } = useParams<{ projectId: string }>()
  const navigate = useNavigate()

  useEffect(() => {
    if (!projectId) { navigate('/'); return }
    import('../services/v1/api').then(({ listSnapshots }) =>
      listSnapshots(projectId).then(snaps => {
        const latest = snaps[snaps.length - 1]
        if (latest) {
          navigate(`/p/${projectId}/s/${latest.id}/overview`, { replace: true })
        } else {
          navigate('/', { replace: true })
        }
      }).catch(() => navigate('/', { replace: true }))
    )
  }, [projectId, navigate])

  return (
    <div className="grepo-app">
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '60vh', gap: 12 }}>
        <span className="spinner" aria-hidden="true" />
        <span>Loading project…</span>
      </div>
    </div>
  )
}

// ── Exported layouts ───────────────────────────────────────────────────────

export function WorkspaceLayout() {
  return (
    <WorkspaceProvider>
      <WorkspaceInner />
    </WorkspaceProvider>
  )
}

export { ProjectRoot }

